DROP TABLE IF EXISTS `attractions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `attractions` (
  `Attraction_ID` int NOT NULL AUTO_INCREMENT,
  `Name` varchar(255) NOT NULL,
  `Object_Type_ID` int DEFAULT NULL,
  `Category_ID` int DEFAULT NULL,
  `Description` text,
  `Admin_Location_ID` int DEFAULT NULL,
  `Latitude` decimal(10,7) NOT NULL,
  `Longitude` decimal(10,7) NOT NULL,
  `Accessibility` text,
  `City_Distance` decimal(10,7) DEFAULT NULL,
  `Key_City_ID` int DEFAULT NULL,
  `History` text,
  `Legends` text,
  `Object_Value_ID` int DEFAULT NULL,
  `Object_Value_Status_ID` int DEFAULT NULL,
  `Object_Value_Description` text,
  `Modernity` text,
  `Recreation_Potential_ID` int DEFAULT NULL,
  `Recreation_Potential_Description` text,
  `Season_ID` int DEFAULT NULL,
  `Time_Recommendation` varchar(255) DEFAULT NULL,
  `Visitor_Requirements` varchar(1024) DEFAULT NULL,
  `Rules` text,
  `Guides` text,
  `Price` decimal(10,2) DEFAULT NULL,
  `Relief` text,
  `Geomorphology_ID` int DEFAULT NULL,
  `Geologic` text,
  `Climate` text,
  `Hydrology` text,
  `Flora_Fauna` text,
  `Ecologic` text,
  `Creation_Date` varchar(255) DEFAULT NULL,
  `Author_ID` int DEFAULT NULL,
  `Style_Architecture` text,
  `Materials_and_Technologies` text,
  `Creation_Purpose_ID` int DEFAULT NULL,
  `Technical_Condition_ID` int DEFAULT NULL,
  `Object_Status_ID` int DEFAULT NULL,
  `Owner_ID` int DEFAULT NULL,
  `Restoration_Works` text,
  `TCI` varchar(255) DEFAULT NULL,
  `Created` datetime DEFAULT CURRENT_TIMESTAMP,
  `Last_Updated` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `Creator_User_ID` int DEFAULT NULL,
  `Last_Updated_User_ID` int DEFAULT NULL,
  `Deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`Attraction_ID`),
  KEY `Object_Type_ID` (`Object_Type_ID`),
  KEY `Category_ID` (`Category_ID`),
  KEY `Admin_Location_ID` (`Admin_Location_ID`),
  KEY `Key_City_ID` (`Key_City_ID`),
  KEY `Object_Value_ID` (`Object_Value_ID`),
  KEY `Object_Value_Status_ID` (`Object_Value_Status_ID`),
  KEY `Recreation_Potential_ID` (`Recreation_Potential_ID`),
  KEY `Season_ID` (`Season_ID`),
  KEY `Geomorphology_ID` (`Geomorphology_ID`),
  KEY `Author_ID` (`Author_ID`),
  KEY `Creation_Purpose_ID` (`Creation_Purpose_ID`),
  KEY `Technical_Condition_ID` (`Technical_Condition_ID`),
  KEY `Object_Status_ID` (`Object_Status_ID`),
  KEY `Owner_ID` (`Owner_ID`),
  KEY `Creator_User_ID` (`Creator_User_ID`),
  KEY `Last_Updated_User_ID` (`Last_Updated_User_ID`),
  CONSTRAINT `attractions_ibfk_1` FOREIGN KEY (`Object_Type_ID`) REFERENCES `object_types` (`Object_Type_ID`),
  CONSTRAINT `attractions_ibfk_10` FOREIGN KEY (`Author_ID`) REFERENCES `authors` (`Author_ID`),
  CONSTRAINT `attractions_ibfk_11` FOREIGN KEY (`Creation_Purpose_ID`) REFERENCES `creation_purposes` (`Creation_Purpose_ID`),
  CONSTRAINT `attractions_ibfk_12` FOREIGN KEY (`Technical_Condition_ID`) REFERENCES `technical_conditions` (`Technical_Condition_ID`),
  CONSTRAINT `attractions_ibfk_13` FOREIGN KEY (`Object_Status_ID`) REFERENCES `object_statuses` (`Object_Status_ID`),
  CONSTRAINT `attractions_ibfk_14` FOREIGN KEY (`Owner_ID`) REFERENCES `owners` (`Owner_ID`),
  CONSTRAINT `attractions_ibfk_15` FOREIGN KEY (`Creator_User_ID`) REFERENCES `users` (`User_ID`),
  CONSTRAINT `attractions_ibfk_16` FOREIGN KEY (`Last_Updated_User_ID`) REFERENCES `users` (`User_ID`),
  CONSTRAINT `attractions_ibfk_2` FOREIGN KEY (`Category_ID`) REFERENCES `categories` (`Category_ID`),
  CONSTRAINT `attractions_ibfk_3` FOREIGN KEY (`Admin_Location_ID`) REFERENCES `admin_location` (`Admin_Location_ID`),
  CONSTRAINT `attractions_ibfk_4` FOREIGN KEY (`Key_City_ID`) REFERENCES `admin_location` (`Admin_Location_ID`),
  CONSTRAINT `attractions_ibfk_5` FOREIGN KEY (`Object_Value_ID`) REFERENCES `object_values` (`Object_Value_ID`),
  CONSTRAINT `attractions_ibfk_6` FOREIGN KEY (`Object_Value_Status_ID`) REFERENCES `object_value_statuses` (`Object_Value_Status_ID`),
  CONSTRAINT `attractions_ibfk_7` FOREIGN KEY (`Recreation_Potential_ID`) REFERENCES `recreation_potentials` (`Recreation_Potential_ID`),
  CONSTRAINT `attractions_ibfk_8` FOREIGN KEY (`Season_ID`) REFERENCES `seasons` (`Season_ID`),
  CONSTRAINT `attractions_ibfk_9` FOREIGN KEY (`Geomorphology_ID`) REFERENCES `geomorphologies` (`Geomorphology_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=102 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
