INSERT INTO `attractions` VALUES (78,'Школьный краеведческий музей села Голуметь',1,NULL,'Учреждение при МКОУ СОШ с. Голуметь, которое хранит историю села и занимается патриотическим воспитанием. Музей был создан 5 ноября 1974 года под руководством учителя биологии Галины Кузьминичны Гурулёвой',1,53.0373460,102.3500120,'асфальтовое покрытие, гравийная дорога',65.0000000,1,'Село Голуметь в Черемховском районе Иркутской области имеет богатую историю. Существует несколько версий даты его основания: по данным карт Семёна Ремезова, село возникло в конце XVII века, но позднее была установлена более ранняя дата — 1548 год. В конце XVIII века Голуметь стало крупным купеческим центром. Через село проходил монгольский путь, и оно служило перевалочным пунктом в торговле с Монголией. Местные купцы обменивали соль и мыло на кожу и ткани. К тому времени в Голумети проживало до 48 купцов, половина из которых относилась к первой гильдии. Многие имели свои лавки в Иркутске, заводы и фабрики. В 1914 году в селе был построен православный храм Святителя Николая Чудотворца (Свято-Никольский храм). Он стал центром религиозной жизни, но после прихода советской власти был закрыт. В 2002 году здание признали аварийным, началась реставрация, и сегодня храм снова действует. В годы Гражданской войны Голуметь стало центром восстания против большевистской власти. В октябре 1920 года здесь располагался штаб крестьянского восстания. При его подавлении в селе было расстреляно несколько десятков человек. В советское время в Голумети был организован совхоз «Голуметский» с пашнями, фермой, лесозаготовительным участком и зверопромхозом. Также работали маслозавод, пошивочный цех, заготавливались грибы, ягоды и орехи. Однако с 1992 года большинство предприятий закрылось.','Существует три легенды об образовании Голумети и происхождении её названия: Легенда о рыбаке и бурятах. В этих местах жило богатое племя бурят, которые имели много земель. По ним протекали реки Белая и Иретка, в которых водилось много рыбы. Однако буряты ели рыбу редко, так как у них не было средств для ловли. Однажды они увидели русского мужика, который варил на костре ушицу. Он пригласил бурят отведать рыбу, достал солёного сига и тайменя. Удивившись, как один человек наловил столько рыбы, буряты попросили продать ему сеть. Мужик согласился, но с условием, что поселится на их земле навечно. Так и возникла Голуметь, поскольку «гульма» в переводе с бурятского означает «сеть». Легенда о «голой меди». По преданию, пришлые люди, увидев богатые рыбой и зверем земли, которые принадлежали одному зажиточному буряту, так загорелись желанием их приобрести, что предложили за землю «голую медь». Так и появилась в XVI–XVII веках Голуметь — место, купленное за «голую медь». Эвенкийская версия. Название может происходить от эвенкийского «голо» — «обгоревшее бревно, чурка», «лабаз (настил на сваях)» или «голомо» —  «чум из расколотых пополам брёвен, покрытый лиственной корой и засыпанный на зиму землёй или снегом».',NULL,NULL,NULL,'Музей расположен в здании МКОУ СОШ с. Голуметь. Благоустройство: информационные стенды с описанием экспозиций; оборудованные залы для экспозиций; места для проведения экскурсий и занятий.Смотровые площадки, беседки, мусорные баки и туалеты непосредственно на территории музея не предусмотрены — они относятся к инфраструктуре школы.',NULL,'Музей ориентирован на культурно-познавательный туризм. Возможности: экскурсии по экспозициям; знакомство с историей села, природой края, народными промыслами; участие в краеведческих мероприятиях и встречах; фотофиксация экспонатов (с разрешения администрации).',NULL,'1-1,5 ч',NULL,'В музее действуют следующие правила: запрещено трогать экспонаты без разрешения экскурсовода; нельзя шуметь, мешать проведению экскурсий и занятий; запрещено курить, употреблять пищу и напитки в залах; необходимо соблюдать чистоту и порядок; фотографировать можно только с разрешения администрации.','Экскурсии проводят: учителя и сотрудники школы; учащиеся краеведческого кружка «Юный краевед». Для организации экскурсии необходимо заранее связаться с администрацией школы.',0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:46:20','2026-06-01 04:46:20',1,1,0),(79,'Дом купца Раджабова',1,NULL,'Исторический памятник в селе Голуметь Черемховского района Иркутской области. Это единственный сохранившийся в районе образец городской архитектуры начала XX века',1,53.0433830,102.3680150,'асфальтовое покрытие, гравийная дорога',65.0000000,1,'После окончания Кавказской войны (1870–1880-х годов) аварец Рамазан Раджабов был сослан в Сибирь и поселился в Голумети. Он женился на татарской девушке, у них родилось 7 сыновей и 3 дочери. Сыновья занялись торговлей, наиболее известными стали Мурат, Семён и Рамзан. Наибольшим авторитетом в семье пользовался Мурат Раджабов. Его торговое предприятие имело годовой оборот 20 тысяч рублей и поддерживало торговые связи с Монголией и Китаем. В конце XIX — начале XX века он построил в Голумети двухэтажный дом, где на нижнем этаже располагался магазин, а на верхнем жила его семья. Семья Раджабовых внесла вклад в развитие села. Мурат Раджабов открыл начальную школу, где могли обучаться не только дети купцов, но и дети крестьян. В годы Гражданской войны богатство братьев привлекало внимание бандитов. По воспоминаниям потомков, некоторые из Раджабовых укрылись в тайге, а Мурат Раджабов был убит после революции как классовый враг народа. После установления советской власти Раджабовы разъехались по Иркутской области, некоторые вернулись на Кавказ.','В некоторых источниках упоминается, что в особняке Раджабова был собственный зимний сад. Однако это не подтверждено документально и может относиться к категории местных легенд.',NULL,NULL,NULL,'Дом находится в аварийном состоянии и не приспособлен для посещения. В нём нет смотровых площадок, информационных стендов, беседок, мусорных баков или туалетов.',NULL,'Его можно включить в программу экскурсий по селу Голуметь, чтобы познакомиться с историей купеческой эпохи.',NULL,'10-15 мин',NULL,'Посещение дома без разрешения администрации или экскурсовода запрещено. Необходимо соблюдать режим охраны объекта культурного наследия: не повреждать стены, не заходить внутрь, если доступ закрыт.','Дом купца Раджабова входит в программу экскурсий, которые организует Голуметский сельский Дом культуры.',0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:46:20','2026-06-01 04:46:20',1,1,0),(80,'Поклонный крест ',9,NULL,'Поклонный крест в селе Голуметь Черемховского района был установлен 19 мая 2025 года на въезде в село. Этот проект стал победителем районного конкурса «Лучший проект ТОС» Черемховского района',1,53.0448230,102.3881140,'асфальтовое покрытие',65.0000000,1,'Поклонный крест на въезде в село Голуметь был установлен 19 мая 2025 года в рамках реализации районного конкурса «Лучший проект ТОС» Черемховского района. Проект стал победителем конкурса, а его реализация стала возможна благодаря участию администрации Голуметского муниципального образования, поддержке мэра района С. В. Марача и других лиц. Изготовил и установил объект известный иркутский скульптор Данила Сафонов. Ранее он работал над обелиском Славы и памятником участникам специальной военной операции в том же селе. Традиция установки поклонных крестов на Руси возникла задолго до крещения в 988 году и восходит ко временам апостола Андрея. Такие кресты воздвигались на открытых, часто возвышенных местах: для поклонения там, где не было храмов и часовен, на месте гибели христиан, на месте будущего или ранее разрушенного храма, на границах поселений и даже в качестве ориентира. В советское время традиция установки крестов прервалась, но в 1990-е годы начала возрождаться, часто — на месте разрушенных храмов','В традициях установки поклонных крестов часто присутствует символическое значение: такие кресты могли рассматриваться как зримое воплощение молитвы к Господу об избавлении от всякого зла, а также как «охранные», оберегающие жителей поселения от болезней и неприятностей.',NULL,NULL,NULL,'На другой стороне дороги располагается въездная стела в село',NULL,'Может быть частью туристического маршрута по селу Голуметь, которое интересно историей купеческого прошлого и сохранившимися купеческими домами.',NULL,'10-15 мин',NULL,'При посещении любых религиозных объектов, рекомендуется соблюдать благоговейное отношение, не повреждать объект и окружающую территорию.',NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:46:21','2026-06-01 04:46:21',1,1,0),(81,'Полежаевская гидроэлектростанция',1,6,'Полежаевская гидроэлектростанция — малая ГЭС, расположенная в Черемховском районе Иркутской области на реке Большая Иреть (в переводе с бурятского — «лиственничный бор»). Она была построена в 1950–1954 годах и проработала до 1976 года. Находится в заброшенном состоянии.',1,52.9650600,102.3309480,'гравийная, глиняная дорога (весной и осенью может потребоваться проходимая машина)',74.0000000,1,'Полежаевская ГЭС стала одним из первых объектов электрификации в Черемховском районе, где в конце 1940-х годов началась сплошная электрификация. Это было связано с производственной необходимостью города шахтёров Черемхово. К 1950-м годам благодаря, в том числе Полежаевской ГЭС, все колхозы в районе были электрифицированы. При строительстве станции пришлось изменить русло реки: был прорыт канал длиной 700 метров, шириной 10–15 метров, который позволил добиться большего перепада высот и скорости воды. Из-за этого часть жителей была переселена. Первый директор ГЭС — участник Великой Отечественной войны Илья Григорьевич Васильев. С 1955 по 1959 год коллектив электростанции состоял из 26 человек. Станция обеспечивала электроснабжение не только Черемховского, но и части Заларинского и Аларского районов. Её мощность не превышала 800 кВт (две турбины по 400 кВт каждая). Оборудование для ГЭС было получено в порядке репараций после Великой Отечественной войны: электрооборудование фирмы Siemens-Schuckertwerke (Германия), гидравлическое — концерна Voith GmbH (Австрия). Инструкции по установке и эксплуатации были на немецком языке, поэтому оборудование монтировали по подстрочному переводу. Работа Полежаевской ГЭС способствовала развитию сельского хозяйства в регионе: увеличилось поголовье крупного рогатого скота, появились возможности для расширения посевов зерновых культур. Станция прекратила работу после появления крупных ГЭС на Ангаре (Иркутской, Братской) и магистральных ЛЭП 110, 220 кВ. В конце 1970-х годов её списали с баланса Иркутских электрических сетей, и объект стал бесхозным.',NULL,NULL,NULL,NULL,'На территории нет смотровых площадок, информационных стендов, беседок, туалетов или мусорных баков. Здание станции лишено крыши, оборудование отсутствует, плотина частично разрушена.',NULL,'Место привлекает любителей индустриального туризма и фотографов. Посетители могут прогуляться по высокой дамбе канала, насладиться видами на реку и окрестности, устроить пикник на солнечных полянах вдоль канала. Некоторые местные жители летом купаются в реке Иреть у плотины.',5,'1-2 ч.','Физическая подготовка — минимальная, так как требуется лишь прогулка по относительно ровной местности.','соблюдать осторожность при ходьбе по руинам и дамбе — есть риск обвала или падения; не трогать разрушенные конструкции и не проникать в опасные зоны; не оставлять мусор; учитывать, что территория не охраняется, и соблюдать меры личной безопасности.',NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:46:21','2026-06-01 04:46:21',1,1,0),(82,'Библиотека села Онот',1,NULL,'Библиотека открылась в 1958 году в небольшом посёлке, где добывали тальк. Первоначально она занимала маленькую комнату в помещении клуба',1,52.7372970,102.0443120,'грунтовая дорога, может потребоваться проходимый автомобиль',112.0000000,1,'Историческая справка. Библиотека открылась в 1958 году в молодом посёлке, где добывали тальк. Первоначально она занимала маленькую комнату в помещении клуба. В 2021 году библиотека села Онот была признана одной из лучших в Иркутской области и стала победителем областного конкурса «Лучшие сельские учреждения культуры и их работники».',NULL,NULL,NULL,NULL,'Библиотека предоставляет базовые услуги: есть бесплатный Wi-Fi, парковка, туалет, разрешены фото- и видеосъёмка',NULL,'Библиотека может быть интересна туристам, которые хотят узнать о истории села и края, поучаствовать в тематических мероприятиях или выставках местного творчества.',NULL,'1-2 ч',NULL,'Стандартные правила поведения в библиотеке: соблюдение тишины, бережное отношение к книгам и имуществу учреждения.','Библиотекари могут проводить тематические экскурсии и рассказывать об истории села и библиотеки.',0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:46:21','2026-06-01 04:46:21',1,1,0),(83,'Храм во имя святителя Иннокентия',1,NULL,'Храм во имя святителя Иннокентия в селе Онот Черемховского района — первый храм в истории села. Он расположен на берегу реки Онот и выполнен в виде небольшого деревянного здания по канонам православной архитектуры. Звонница оснащена пятью колоколами, которые доставили из города Тутаев Ярославской области.',1,52.7353930,102.0473160,'грунтовая дорога, может потребоваться проходимый автомобиль',112.0000000,1,'История храма началась в 2008 году по благословению митрополита Вадима. В 2009 году был зарегистрирован приход, освящён участок под строительство и отслужена первая литургия — тогда ещё в простом сарае. Фундамент заложили в 2011 году, а в 2012-м построили сруб храма и освятили крест для храмового купола. Первая Божественная литургия в здании нового храма прошла 22 февраля 2016 года — в день памяти обретения мощей святителя Иннокентия Иркутского. В 2022 году была построена колокольня, приобретены и освящены колокола. Освящение храма состоялось 16 июля 2025 года. Чин освящения и Божественную литургию совершили два архиерея: митрополит Иркутский и Ангарский Максимилиан и епископ Братский и Усть-Илимский Константин. В торжественный день митрополит Максимилиан вручил епархиальные и приходские грамоты особо потрудившимся в строительстве храма. В строительных работах участвовали жители села разных специальностей. Неоценимую помощь оказали предприниматели Сергей Костюков и Дмитрий Коткин.',NULL,NULL,NULL,NULL,'Прихрамовая территория была облагорожена прихожанами: высажены цветы, кустарники, молодые саженцы сосен и елей. Однако информации о наличии смотровых площадок, информационных стендов, беседок, мусорных баков или туалетов в открытых источниках нет.',NULL,'Храм может быть интересен туристам, которые интересуются православной архитектурой и историей региона. Также возможно проведение экскурсий',NULL,'30 мин.',NULL,'В храме действуют стандартные правила поведения: нельзя шуметь, пользоваться мобильным телефоном (его следует поставить на беззвучный режим); не рекомендуется сидеть во время службы, если нет медицинских ограничений; женщинам полагается иметь на голове платок или головной убор, мужчинам — снимать головной убор; запрещено проходить между амвоном и центральным аналоем во время молитвы священнослужителей; нельзя целовать святыни храма и участвовать в Таинстве Святого Причащения с накрашенными губами; на территории храма запрещается выгул собак, непристойная брань, курение и распитие спиртных напитков.',NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:46:21','2026-06-01 04:46:21',1,1,0),(84,'Экологическая тропа «БОТы» («Большая Онотская Тропа»).',1,NULL,'экологическая тропа «БОТы» создана в рамках проекта «Живая тайга» (2021) в селе Онот Черемховского района. Маршрут включает деревянный мост через протоку реки Онот, смотровую площадку на Китаевой горе, арт, объекты и зоны отдыха. Тропа способствует развитию экотуризма и знакомству с природой региона.',1,52.7364890,102.0546890,'грунтовая дорога, может потребоваться проходимый автомобиль',112.0000000,1,'Проект «Живая тайга», получивший грантовую поддержку Фонда президентских грантов в 2021 году, был направлен на развитие туризма и благоустройство территории в селе Онот Черемховского района Иркутской области. В рамках проекта был открыт туристический маршрут в село и создана экологическая тропа «БОТы» (Большая Онотская Тропа). На экотропе были размещены различные объекты, которые сделали маршрут более комфортным и интересным для посетителей:Качели и скамейки. Эти элементы благоустройства позволили туристам отдыхать и наслаждаться природой во время прогулки. Фигуры-габионы. Это арт-объекты, созданные с использованием техники габионов (конструкций из сетчатых контейнеров, заполненных камнями или другими материалами). Они стали частью ландшафтного дизайна тропы. Деревянный мост через сухую протоку реки Онот. Сооружение обеспечило безопасный переход через водную преграду и улучшило доступность маршрута. Смотровая площадка на Китаевой горе. С неё открывается вид на посёлок и его окрестности. Это место стало одним из ключевых пунктов тропы, привлекающим туристов. Также в рамках проекта организовывались однодневные туристические экскурсии по маршруту «Голуметь — Онот». В программу включалось знакомство с творчеством художника-самородка Михаила Игумнова, посещение участка экологической тропы, местного православного храма и ярмарки «Дары тайги». На ярмарке местные жители продавали дикоросы (грибы, ягоды, кедровые шишки), что позволяло им получать дополнительный доход.Открытие Большой Онотской тропы «БОТы» состоялось 8 октября 2021 года. В мероприятии участвовали все участники проекта «Живая тайга». Проект заложил основу для дальнейшего развития туризма в регионе. Позже возникла идея его продолжения — проекта «Живая тайга-2», который был нацелен на создание безопасных условий для передвижения туристов по тропе, особенно в зимний период.',NULL,4,NULL,NULL,'смотровая площадка на Китаевой горе; деревянный мост через сухую протоку реки Онот; качели и скамейки для отдыха; фигуры?габионы как арт?объекты; информационные стенды (предполагаются, но данные требуют уточнения); мусорные баки (по маршруту); туалеты — отсутствуют.',NULL,'пешие прогулки и треккинг; отдых на природе (скамейки, качели); фототуризм (виды с Китаевой горы, арт-объекты); экологическое просвещение (информационные стенды); участие в экскурсиях и ярмарках «Дары тайги».',6,'2–3 часа на осмотр тропы с отдыхом и фотосессией; полный маршрут с экскурсией — 4–6 часов.','физическая подготовка — средняя (маршрут с небольшими подъёмами); экипировка — удобная обувь, одежда по погоде; зимой — лыжи или снегоступы для комфортного передвижения.','запрещено мусорить, разводить костры вне отведённых мест; не повреждать арт?объекты, скамейки, мост; соблюдать тишину и бережное отношение к природе; режим охраны — нет строгого режима, но территория находится под наблюдением местных активистов и администрации.','Экскурсии организует инициативная группа проекта «Живая тайга». Контакты можно уточнить в администрации села Онот или Черемховского муниципального образования.',0.00,'Рельеф включает склоны, долину реки Онот и сухую протоку.',5,'типичные для региона осадочные и магматические породы. Полезные ископаемые и палеонтологические находки на маршруте не отмечены','резко континентальный климат; летом — умеренно тепло (+15…+25 °C), зимой — холодно (?20…?30 °C). Возможны сильные ветры на возвышенностях.','тропа расположена вблизи реки Онот; на маршруте — сухая протока, через которую построен деревянный мост. Источники воды на тропе не указаны.','флора — смешанные леса (сосна, ель, берёза), кустарники, травянистые растения; фауна — типичные виды тайги (белки, птицы, мелкие грызуны); крупные животные редки из?за близости села; сезонные изменения: весной — цветение, летом — зелень, осенью — яркая листва, зимой — заснеженные пейзажи','антропогенная нагрузка — умеренная (рост числа туристов после открытия тропы); угрозы — замусоривание, вытаптывание растительности; меры по сохранению — регулярная уборка, информационные стенды о правилах поведения, вовлечение местных жителей в охрану тропы.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:46:21','2026-06-01 04:46:21',1,1,0),(85,'Онотское месторождение талька',2,1,'Месторождение высококачественного маложелезистого талька-стеатита, приуроченное к докембрийским метаморфическим породам фундамента Сибирской платформы. Состоит из восьми разобщённых участков и ряда мелких проявлений, локализованных в зонах двух разломов.',1,52.7364890,102.0546890,'Почти вся дорога проходит через тайгу. В период распутицы (весна, осень) проезд может быть затруднён.',112.0000000,1,'Месторождение известно с 1830 года. Добыча началась в 1946 году, что привело к появлению посёлка Онот. В советское время месторождение считалось крупнейшим в стране, а онотский тальк ценился европейскими предприятиями за высокое качество. В 1967 году группе специалистов была присуждена Государственная премия СССР за открытие магнезитов в этом районе.',NULL,5,NULL,NULL,'Туристическая инфраструктура в районе Онотского месторождения талька развита ограниченно, так как основной акцент здесь делается на горнодобывающую деятельность, а не на туризм. Однако в окрестностях села Онот реализуется проект «Живая тайга», который включает создание экологической тропы «БОТы» (Большая Онотская Тропа).',NULL,'Прогулки по экотропе. Маршрут проходит по живописным местам тайги, вдоль реки Онот, с подъёмами на Китаеву гору. Фотоохота и наблюдение за природой. Окружающая тайга богата флорой и фауной, что привлекает любителей фотографии и экотуризма. Пикники. На тропе есть оборудованные места для отдыха (скамейки, площадки). Посещение пещер. В окрестностях села расположена Большая Онотская пещера, которая может быть интересна спелеологам. Активный отдых. Возможность прогулок на снегоходах или санях зимой, сплавов по реке (с учётом сезона и условий)',NULL,'Для осмотра экотропы «БОТы» и основных достопримечательностей села достаточно 1–2 часов. Если планируется посещение пещер или дополнительные активности (сплавы, прогулки на снегоходах), время визита стоит увеличить до полного дня.','Физическая подготовка. Тропа включает подъёмы и спуски, поэтому требуется базовая выносливость. Экипировка. Рекомендуется носить удобную обувь (треккинговые ботинки), тёплую одежду в прохладное время года, дождевик или зонт на случай осадков. Для посещения пещер понадобится фонарик и возможно страховочное оборудование. Средства защиты от насекомых и клещей, особенно в тёплое время года.','Соблюдение режима охраны территории. Если участок находится в границах особо охраняемых природных территорий, действуют ограничения, установленные федеральным законом. Запрет на сбор растений, минералов и вмешательство в природную среду. Обязательная утилизация мусора. Не оставлять отходы на тропе или в окрестностях. Соблюдение правил пожарной безопасности. Запрещено разжигать костры в неположенных местах. Ограничения в период неблагоприятных погодных условий. В дождь или снег некоторые участки тропы могут быть закрыты из-за высокого риска травм.',NULL,0.00,'Рельеф характеризуется крутыми склонами и горными массивами.',6,'Месторождение приурочено к выступу фундамента Сибирской платформы. Продуктивная толща (мощность 2300–2650 м) сложена гнейсами, амфиболитами, магнезитами и другими магнезиально-карбонатными породами. Рудные тела представлены жилами, штоками, линзами и пластообразными залежами протяжённостью до 600 м и мощностью 2–90 м.',NULL,'Рядом протекает река Онот, которая разделяет село на две части.',NULL,'Информация о текущем экологическом состоянии месторождения в открытых источниках не представлена. Однако известно, что переработка сырья происходит за пределами Онота, что может снижать локальную нагрузку на окружающую среду.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:46:21','2026-06-01 04:46:21',1,1,0),(86,'Свято-Никольский храм',9,NULL,'Один из самых значительных сельских храмов Приангарья, построенный в 1914 году. Это трёхпридельный крестово-купольный храм в русско-византийском стиле с пятью главами и центральной широкой ротондой под полусферой.',1,53.0400280,102.3613880,'асфальтовое покрытие, гравийная дорога',65.0000000,1,'Первая деревянная церковь в Голумети была построена в 1779 году, но вскоре сгорела. В XVIII веке в селе возвели круглогодичную Николаевскую и летнюю Троицкую церкви. Николаевская церковь сгорела в 1820 году, на её месте построили наполовину каменную одноэтажную церковь, которая вскоре пришла в упадок из-за слабого грунта. В 1876 году священником стал отец Фортунат Румянцев. Вместе с председателем церковно-приходского попечительства Гавриилом Невидимовым он начал сбор средств на строительство нового храма. Почти за 20 лет было собрано около 40 тысяч рублей, но Русско-японская война и последовавшая инфляция обесценили эти средства, и строительство пришлось отложить. Работы возобновились в 1910 году по проекту иркутского архитектора Николая Дудицкого, выпускника Санкт-Петербургского института гражданских инженеров. Камень для строительства возили из окрестностей села, кирпич производили на месте. Для кладки стен использовали яичные желтки, которые собирали со всех дворов села. Все подготовительные работы выполняли местные крестьяне. Храм был построен за три года — с июня 1910 года по ноябрь 1913 года. 20 января 1914 года главный храм во имя святителя Николая освятил киренский епископ Евгений, а 3 и 4 февраля того же года благочинный священник Алексей Логинов освятил боковые приделы во имя Святой Троицы и Покрова Пресвятой Богородицы. Приход на момент освящения насчитывал более 4 500 человек. Церковь действовала до 1936 года, после чего была закрыта. В разные годы в здании размещались склад Заготзерна, кинотеатр, загон для скота. В 1987 году храм признали памятником областного значения.','Существует история, связанная с иконой Николая Чудотворца. Во время гонений на церковь в советские годы икона была спасена жительницей соседней деревни Нижняя Иреть. Она хранила её в амбаре до 1970-х годов. Позже икона перешла к её родственнику — известному певцу Леониду Харитонову. Он оплатил реставрацию и вернул святыню в храм.',NULL,NULL,NULL,NULL,NULL,'Территория вокруг храма может быть интересна для фотосессий. В окрестностях села есть возможности для пеших прогулок, знакомства с природой региона.',NULL,'30 мин',NULL,'в храме действуют стандартные правила поведения, принятые в православных храмах: нельзя шуметь, мешать богослужениям, трогать исторические объекты. Запрещено курить, употреблять алкоголь, оставлять мусор.',NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:46:21','2026-06-01 04:46:21',1,1,0),(87,'Площадь и памятник Владимиру Ленину',1,4,'В 1954 году строители сдали в эксплуатацию строгое по стилю здание горкома КПСС. В начале 1960 года бюро городского комитета КПСС и руководство горисполкома принимают совместное постановление о сооружении на Первомайской площади памятника Владимиру Ильичу Ленину. 5 ноября 1960 года, в канун празднования Великого Октября, на площади у здания городского комитета КПСС в торжественной обстановке был открыт памятник Владимиру Ленину. В 1963 году эта площадь стала носить его имя. Фигура вождя, отлитая из чистой бронзы весом 3,5 тонны. Его авторами были архитектор Александр Полосов и скульптур Руковишников.',1,53.1372960,103.0894290,'асфальтированная дорога',0.0000000,1,'В 1954 году строители сдали в эксплуатацию строгое по стилю здание горкома КПСС. В начале 1960 года бюро городского комитета КПСС и руководство горисполкома принимают совместное постановление о сооружении на Первомайской площади памятника Владимиру Ильичу Ленину. 5 ноября 1960 года, в канун празднования Великого Октября, на площади у здания городского комитета КПСС в торжественной обстановке был открыт памятник Владимиру Ленину. В 1963 году эта площадь стала носить его имя. Фигура вождя, отлитая из чистой бронзы весом 3,5 тонны. Его авторами были архитектор Александр Полосов и скульптур Руковишников. С именем Ленина связаны некоторые страницы жизни черемховских шахтеров в 20-е годы. 2 августа 1920 года шахтеры Черемхово проводили своих делегатов в Москву. 15 сентября Ленин принял наших земляков, долго беседовал с ними о работе на черемховских копях и отправил с делегацией письмо, в котором выразил удовлетворение работой по восстановлению народного хозяйства.',NULL,6,NULL,NULL,'В 2026 году город планирует участвовать во Всероссийском конкурсе лучших проектов создания комфортной городской среды с проектом благоустройства площади Ленина и прилегающих территорий. Жителям предлагали выбрать постоянные объекты и сезонные мероприятия. Среди возможных вариантов — скамейки и зоны отдыха, детская игровая площадка, спортивная площадка, фонтан или водный объект, клумбы и зелёные насаждения, велосипедные дорожки, беседки и навесы от дождя и другие.',NULL,NULL,NULL,'10-30 минут',NULL,NULL,NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:36','2026-06-01 04:48:36',1,1,0),(88,'Музей истории города Черемхово',9,5,'Музей истории города Черемхово — краеведческий музей, расположенный в Иркутской области. Он был создан в 2019 году путём объединения Музея истории Черембасса и Выставочного зала им. В. А. Инешина.',1,53.1376300,103.0877330,'асфальтированная дорога',0.0000000,1,'Создание краеведческого музея в Черемхово планировалось еще до войны, инициатор создания – Петр Францевич Требуховский, художник, педагог и краевед, доцент Иркутского педагогического института, действительный член ВСОРГО, инициатор и участник краеведческих экспедиций, создатель студии изобразительного искусства для детей и взрослых при Черемховском педагогическом училище. На страницах газеты «Черемховский рабочий» проводилась большая агитационная работа по поиску и сохранности предметов старины, черемховцы собирали предметы быта (будущие экспонаты) для того, чтобы пополнить коллекцию будущего музея. Открытие планировалось к 24-летию Социалистической революции, 7 ноября 1941 года. В новом двухэтажном здании Центральной библиотеки было выделено помещение, горисполком направил на создание музея 25 тыс. рублей. Но война внесла свои коррективы. И только через 27 лет мечта черемховцев об открытии городского музея осуществилась. Черемховский горисполком народных депутатов принял решение о сохранении исторических документов, реликвий, фотографий, исторических сведений, и 29 февраля 1969 года в городе на общественных началах открылся историко-краеведческий музей. Отдельного здания не было, музей размещался в приспособленном помещении: трех комнатах бывшего общежития, где, к сожалению, обеспечение сохранности было неудовлетворительным. 29 сентября 1977 г., после длительного перерыва, музей открылся вновь. Директор — Маргарита Михайловна Ларионова. В 1985 г. музей переезжает в здание бывшего Дома культуры угледобывающего разреза, где также располагается драмтеатр. В 1986 году музей передают на баланс разрезу «Черемховский». Фонды музея пополняются предметами, свидетельствующими о развитии угольной промышленности в Черемховском угольном бассейне. В течение двух лет, с мая 1987 г. по июнь 1989-го, создается постоянная экспозиция «Историко-краеведческого музея Черемховских шахтеров», рассчитанная на посещаемость в год 17-18 тыс. человек. Музей располагает 5100 историческими экспонатами, из них подлинных — 2652. Директор музея истории Черембасса — Чернигова Анна Елизаровна. В 2003 году музей передан в подчинение Отдела культуры администрации города Черемхово и входит, в качестве структурного подразделения «Музей истории Черембасса», в Культурно-досуговый центр. Музей вновь переезжает, на этот раз – в специально выстроенное деревянное здание в центре города. К сожалению, площади нового здания были крайне недостаточны для музея. 10 июля 2019 года Постановлением администрации города Черемхово за № 511 от 26.06.2019 г. было зарегистрировано юридическое лицо Муниципальное бюджетное учреждение культуры «Музей истории г. Черемхово», которое стало правопреемником «Музея истории Черембасса». Директором назначена Горбунова Елена Алексеевна. 23 августа 2019 года состоялось торжественное открытие нового учреждения в обновленном помещении. «Музей истории города Черемхово» теперь находится на 1 этаже Дворца культуры «Горняк», расположенного на центральной площади города.',NULL,7,NULL,NULL,'туалеты, мусорные баки, информационные стенды и тд.',NULL,NULL,NULL,'1-2 ч.','Музей доступен для посещения людьми с ограниченными возможностями (есть пандусы и лифты).','Запрещено: касаться экспонатов, фотографировать с вспышкой (в некоторых залах), проносить еду и напитки в залы (кроме воды в закрытой таре), громко разговаривать и мешать другим посетителям.','Экскурсии проводятся по предварительной записи. В музее работают профессиональные экскурсоводы. Контакты для записи: телефон +7 908 653-21-32',150.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:36','2026-06-01 04:48:36',1,1,0),(89,'Музей Владимира Гуркина',1,5,'Музей Владимира Гуркина — отдел музея истории города Черемхово, посвящённый жизни и творчеству драматурга, автора пьесы «Любовь и голуби» Владимира Павловича Гуркина. Он открылся в конце 2023 года в Центральном парке культуры и отдыха Черемхово.',1,53.1379600,103.0771990,'асфальтированная дорога',0.0000000,1,'Музей Владимира Гуркина в Черемхово был открыт в конце декабря 2023 года в Центральном парке культуры и отдыха. Он стал результатом реализации проекта «Парк-театр», который победил во Всероссийском конкурсе лучших проектов создания комфортной городской среды в малых городах и исторических поселениях. Музей создан в рамках федерального проекта «Формирование комфортной городской среды» национального проекта «Жильё и городская среда». Владимир Павлович Гуркин — драматург, актёр и режиссёр, автор пьесы «Любовь и голуби», по которой был снят культовый советский фильм. Он родился в 1951 году в Пермском крае, а в семилетнем возрасте переехал с семьёй в Черемхово, который считал своей второй родиной. Именно здесь формировался его характер, и здесь он черпал вдохновение для своих произведений. Большинство сюжетов его пьес связано с Черемхово, а герои часто были списаны с жителей города. Музей является отделом музея истории города Черемхово, который был обновлён по национальному проекту «Культура» в 2022 году. Экспонаты из фондов музея истории использовали для создания постоянной экспозиции нового отдела.','Творчество Гуркина само по себе стало частью культурного наследия Черемхово. Его пьеса «Любовь и голуби» и одноимённый фильм известны по всей стране, а история создания произведения и жизнь драматурга стали предметом интереса для многих поколений.',NULL,NULL,NULL,'Музей расположен в павильоне, построенном в рамках благоустройства парка. Территория вокруг него благоустроена: обустроены дорожки, проведено освещение, установлено видеонаблюдение и малые архитектурные формы. В самом музее есть интерактивные элементы, цифровые инсталляции, мультимедийное оборудование. Для детей предусмотрена специальная зона с интерактивными активностями.',NULL,'Помимо посещения музея, туристы могут прогуляться по парку, посетить другие достопримечательности Черемхово, связанные с Гуркиным. В парке есть спортивные и детские площадки, пешеходный фонтан, беседки, шахматные столы и другие зоны отдыха.',NULL,'1-2 ч.',NULL,'В музее действуют стандартные правила поведения, характерные для подобных учреждений: запрет на прикосновение к экспонатам, шумное поведение и т. д. Конкретные ограничения могут быть указаны на информационных стендах.','Музей проводит экскурсии. Экскурсионные программы включают «Высокий полёт» для взрослых и молодёжи, а также «В гостях у дедушки Володи» для детей 5–12 лет. Запись на экскурсии, вероятно, требуется заранее. Контакты для связи: телефон +7 908 653-21-32.',150.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:36','2026-06-01 04:48:36',1,1,0),(90,'Граффити космонавта Александра Полещука',1,NULL,'Граффити с изображением Героя России, летчика-космонавта Александра Полещука в одном из домов в Черемхово по улице Ференца Патаки, 4.',1,53.1363340,103.0867140,'асфальтовое покрытие',0.0000000,1,'Полещук родился в Черемхово 30 октября 1953 года. Учился в четвертой школе, сейчас там есть специальный уголок в местном музее. Путь в космонавты был непрост: закончил МАИ, работал в НПО \"Энергия\". С 1982 года активно пытался попасть в отряд космонавтов, но только в 1991 году стал космонавтом-испытателем. Его звёздный час наступил 24 января 1993 года. Полёт сына для мамы, Валентины Сергеевны, был и праздником, и тревогой. Через 179 дней Александр вернулся на Землю. Тогда она всем показывала вырезку из газеты \"Комсомольская правда\", которую хранила несколько лет, где писали о молодом учёном-испытателе, который решил сложнейшую техническую проблему для освоения космоса. Соблюдая секретность (дело было в 80-е годы), фамилию испытателя от читателей скрыли. Но мать знала, что это про её Сашу. Александр Полещук дважды выходил в открытый космос, за это был награжден медалью Алексея Леонова. В 2011 году заслужил медаль \"За заслуги в освоении космоса\". Офицер национального ордена Франции \"За заслуги\". Мэр Черемхово Вадим Семенов пишет в соцсетях: \"Сегодня мы украшаем наш город для того, чтобы молодёжь знала тех людей, которые в свое время приложили много усилий для развития нашей страны. И портрет Александра Фёдоровича Полещука, неслучайно появился на фасаде дома. Он стал 75-м космонавтом России и 289-м космонавтом мира. Так, город Черемхово навеки вошел в историю российского государства как место рождения человека, побывавшего в космосе. И поколение юных черемховцев должно воспитываться на примере своего прославленного земляка и знать, что любая мечта, если к ней стремиться, достижима\".',NULL,8,NULL,NULL,'мусорные баки, скамейки.',NULL,'Объект имеет преимущественно культурно?познавательную и фото-ценность',NULL,'5-15 мин.',NULL,'Поскольку объект находится на фасаде жилого дома, следует соблюдать общепринятые нормы. Запрещено: повреждать фасад и граффити, оставлять мусор, шуметь в позднее время (особенно у окон жилых квартир), залезать на стены или строительные леса (если они есть);',NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:36','2026-06-01 04:48:36',1,1,0),(91,'Модельная библиотека «Интеллект-центр» г. Черемхово',1,NULL,'В библиотеке работает базовая площадка проектной деятельности для школьников и представителей НКО, студия научного эксперимента, лаборатория цифровых ресурсов. Теперь в «Интеллект-центре» можно изучить 3D-моделирование, освоить типографские навыки, научиться создавать мультфильмы и любительское кино. Кроме того, в библиотеке действуют клубы: шахматный, интеллектуального чтения и научного эксперимента.',1,53.1366420,103.0862280,'асфальтовое покрытие ',0.0000000,1,'22 декабря 2020 года в рамках национального проекта «Культура» была открыта модельная библиотека «Интеллект-Центр». В библиотеке выделено несколько модулей: Визит-холл — экспресс-зона ожидания, быстрого поиска информации, получения справок. Трансформер — модуль легко трансформируемых пространств для самозанятости и работы в группах. Интеллектория — персональные рабочие места, доступ к электронным ресурсам, зоны отдыха и общения. Бункер технологий — пространство для реализации творческих и научных идей, проведения опытов и экспериментов. Книжный фонд насчитывает более 2 000 экземпляров. Это книги с дополненной реальностью, книги о науке, робототехнике, шахматах, искусственном интеллекте, истории изобретений, анимации, программировании, самореализации. Библиотеку посещает более 400 читателей разных возрастов и социальных групп. Сегодня «Интеллект-центр» стал для черемховцев пространством самореализации в родном городе.',NULL,9,NULL,NULL,'В библиотеке созданы функциональные зоны (модули), адаптированные для разных видов деятельности. Установлены современные компьютеры, 3D-принтер, 3D-ручки, квадрокоптер, микроскопы, система виртуальной реальности. Есть интерактивная доска и скай-дисплей для анонсов мероприятий. Предоставлен доступ к Wi-Fi и USB-розеткам. Библиотека доступна для людей с ограниченными возможностями здоровья, включая инвалидов-колясочников.',NULL,'Библиотека ориентирована на образовательный и культурный досуг. Здесь можно посетить мастер-классы, интерактивные мероприятия, экскурсии, участвовать в клубах (шахматный, интеллектуального чтения, научного эксперимента). Возможности для творчества: изучение 3D-моделирования, типографских навыков, создание мультфильмов и любительского кино. Проведение квестов, интерактивных викторин и уроков-презентаций.',NULL,'1-2 ч.',NULL,'Стандартные правила поведения в библиотеке: соблюдение тишины в зонах работы, бережное отношение к оборудованию и книгам.','Проводятся экскурсии. Контакты для организации экскурсий: +7 (39546) 5-46-00',0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:36','2026-06-01 04:48:36',1,1,0),(92,'Сквер «Любовь и голуби»',1,NULL,'Скульптурная композиция «Любовь и голуби» была открыта 16 июля 2011 года на перекрёстке улиц Ленина и Ф. Патаки. Идея создания памятника принадлежала мэру Вадиму Семёнову, а проект был одобрен при жизни Владимира Гуркина. Автором скульптуры стал иркутский скульптор Карим Мухамадеев.',1,53.1365870,103.0853160,'асфальтовое покрытие ',0.0000000,1,'Композиция была открыта 6 июля 2011 года на перекрёстке улиц Ленина и Ф. Патаки. Идея создания памятника принадлежала мэру Вадиму Семёнову, проект одобрил сам Владимир Гуркин, а воплотил его иркутский скульптор Карим Мухамадеев. Скульптура изображает сцену примирения главных героев — Нади и Василия Кузякиных. Они сидят на валуне и смотрят друг на друга, а над ними парит стая голубей в форме сердца. Фигуры передают глубокое и нежное чувство любви.','Сквер «Любовь и голуби» в Черемхово тесно связан с реальной историей местных жителей и творчеством драматурга Владимира Гуркина. Прототипами главных героев пьесы и фильма «Любовь и голуби» стали реальные Надежда и Василий Кузякины, которые жили в Черемхово. Гуркин, будучи соседом Кузякиных, использовал их историю в своём произведении, причём даже не сменил имена героев. Согласно воспоминаниям, Василий Кузякин работал на угольной шахте, завёл роман на курорте, ушёл из семьи, но в итоге вернулся к жене. Эта история легла в основу сюжета пьесы. Интересно, что после публикации произведения Кузякины обиделись на Гуркина за то, что он «вынес ссору из избы» и «ославил их на всю страну». Ещё одна легенда связана с похоронами Владимира Гуркина в 2010 году. По свидетельствам очевидцев, во время церемонии прощания стая голубей опустилась на гроб, и их не могли прогнать.',NULL,NULL,NULL,'дорожки, освещение, зелёные насаждения',NULL,'возможность сделать фото, отдохнуть и прогуляться в тени.',NULL,'10-30 мин.',NULL,'Следует соблюдать общие правила: не повреждать объекты, не мусорить, не шуметь в неположенное время.',NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:36','2026-06-01 04:48:36',1,1,0),(93,'Сквер «Первопоселенцев»',1,NULL,'Сквер открыли в 2025 году на улице Первомайской — историческом месте, где проходил Московский тракт. Он стал началом пешего туристического маршрута «Следы. Тракт в городе» протяжённостью 1,8 км.',1,53.1450630,103.0671870,'асфальтовое покрытие ',NULL,1,'Мощение дорожек. Они имитируют тропы к острогам, которые когда-то проходили в этом месте. Дозорная башня Баданового зимовья. Реплика старинной дозорной башни.  Арт-объекты. Они рассказывают о первопоселенцах, прибывших на Черемховский станец в 1743 году, и о главном символе города — черёмухе.  Беседка в центре сквера. Она символизирует единение черемховцев. Внутри расположены скамейки и стол с картой Черемховского поселения 1802 года. По ней можно понять, как выглядело поселение, какие дома и надворные постройки были. Орнамент. Декоративные световые столбы, скамейки и урны украшены черемховским орнаментом, который символизирует черёмуху — гордость города. Сквер стал отправной точкой пешего исторического маршрута протяжённостью 1,8 км по улице Первомайской (ранее — Московскому тракту). На всей протяжённости маршрута установлены информационные стенды с QR-кодами. Проект стал возможен благодаря тому, что в 2025 году Черемхово победило в конкурсном отборе по обустройству туристического кода центра города, организованном Агентством по туризму Иркутской области. На реализацию проекта было выделено более 10,7 млн рублей. Открытие сквера состоялось 5 сентября 2025 года. Сотрудники музея истории города проводили для первых туристов экскурсии.',NULL,10,NULL,NULL,'в центре сквера расположена беседка единения со скамейками и столом, световые столбы, скамейки, урны, установлены информационные стенды с QR-кодами, ведущими на сайт музея истории города.',NULL,'подходит для прогулок, фотосессий (особенно у дозорной башни и в беседке), может использоваться для проведения экскурсий, краеведческих мероприятий',NULL,'20–60 мин.',NULL,'администрация призывает бережно относиться к объекту, не повреждать элементы благоустройства','экскурсии могут проводить сотрудники Музея истории города Черемхово. Контакты музея: ул. Ференца Патаки, 1, телефон +7 (908) 653-2132.',0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:36','2026-06-01 04:48:36',1,1,0),(94,'Могила Гуркина ',1,4,'Владимир Павлович Гуркин — драматург, сценарист, актёр, режиссёр, член Союза писателей России, почётный гражданин Черемхово. Он похоронен на черемховском городском кладбище рядом с могилой своего отца — Павла Васильевича.',1,53.1390480,103.0618120,'асфальтовое покрытие',0.0000000,1,'Владимир Павлович Гуркин (1951–2010) — драматург и сценарист, автор пьесы «Любовь и голуби», которая стала основой для одноимённого фильма Владимира Меньшова. В семилетнем возрасте он переехал с семьёй в Черемхово, где провёл детство и юность. После окончания Иркутского театрального училища работал актёром в Иркутском ТЮЗе, затем в Омском драмтеатре. С 1983 года жил в Москве, работал в театре «Современник», с 1993 года — во МХАТе им. А. П. Чехова. В последние годы жизни активно сотрудничал с Черемховским драматическим театром, где поставил несколько своих пьес. В 2011 году указом губернатора Иркутской области Черемховскому драматическому театру было присвоено имя Владимира Гуркина. Похоронили драматурга в Черемхово — городе, который он считал родным. По завещанию Гуркина, его могила расположена рядом с могилой отчима Павла Васильевича Гуркина, которого писатель считал близким человеком. В 2025 году место захоронения благоустроили: на могилах Гуркина и его родителей установили обелиски с портретами, а ограду украсили фигурками голубей — символом творчества драматурга. Неподалёку оборудовали парковку для посетителей.',NULL,NULL,NULL,NULL,'После благоустройства в 2025 году место захоронения выглядит ухоженным. Установлены обелиски с портретами, ограда украшена фигурками голубей. Рядом оборудована парковка для посетителей.',NULL,'Место подходит для посещения с целью почтения памяти драматурга, фотографирования. Рекреационные активности (пикник, купание и пр.) здесь не предусмотрены.',7,'15-30 мин.',NULL,'На территории кладбища запрещено портить памятники, оборудование, засорять территорию, ломать зелёные насаждения, выгуливать собак и заниматься коммерческой деятельностью.',NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:37','2026-06-01 04:48:37',1,1,0),(95,'Три драматурга',1,4,'Скульптурная композиция посвящена Александру Вампилову, Владимиру Гуркину и Михаилу Варфоломееву — драматургам, так или иначе связанным с городом. ',1,53.1388460,103.0781960,'асфальтовое покрытие',0.0000000,1,'Памятник трём драматургам в Черемхово был открыт 19 июля 2012 года в рамках празднования 95-летия присвоения городу статуса города. Скульптурная композиция посвящена Александру Вампилову, Владимиру Гуркину и Михаилу Варфоломееву — драматургам, так или иначе связанным с Черемхово. Автор работы — иркутский скульптор Карим Мухамадеев. При создании композиции он изучил не только внешность драматургов, но и их произведения, чтобы отобразить многогранный духовный мир авторов. На скульптурной композиции запечатлены беседующие драматурги. Владимир Гуркин вольготно сидит на лавочке, за которой в центре — Михаил Варфоломеев, правее — Александр Вампилов. Почётными гостями церемонии открытия стали мама драматурга Владимира Гуркина — Валентина Петровна, а также его друзья Михаил Розин и Владимир Патис.',NULL,NULL,NULL,NULL,'Памятник расположен на театральной площади (микрорайон Новороссийский) в Черемхово, рядом с Черемховским драматическим театром. Это место доступно для посещения, специальных смотровых площадок, информационных стендов, беседок, мусорных баков или туалетов непосредственно у памятника не упоминается в доступных источниках.',NULL,'Памятник может быть интересен туристам, любителям театра и литературы. Особенность композиции в том, что любой желающий может присесть на скамью рядом с драматургами, вспомнить их литературное наследие и мысленно погрузиться в мир театрального творчества.',NULL,'10-15 мин.',NULL,'Следует соблюдать общепринятые правила поведения: не повреждать объект, не мешать другим посетителям.',NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:37','2026-06-01 04:48:37',1,1,0),(96,'Черемховский драматический театр имени В.П. Гуркина',1,NULL,'Черемховский драматический театр имени В. П. Гуркина — драматический театр в Черемхово Иркутской области. Основан 7 ноября 1939 года спектаклем «Член реввоенсовета» («Год 19-й») И. Прута. В 2011 году театру было присвоено имя Владимира Павловича Гуркина — автора пьесы «Любовь и голуби».',1,53.1391390,103.0782080,'асфальтовое покрытие',0.0000000,1,'Впервые театр в городе появился в 1930-е годы как непрофессиональный театр рабочей молодёжи. Труппа была набрана из заводских и фабричных драмколлективов, но из-за недофинансирования театр проработал недолго. В 1933 году при Доме техники был организован драмколлектив на общественных началах. Он просуществовал до 1939 года, когда открылся профессиональный драматический театр. В первом сезоне (1939/1940) театр поставил 15 пьес и дал 212 спектаклей, которые посмотрели 50 тысяч зрителей. В репертуаре были произведения Островского, Горького, Гольдони, Гюго, Шиллера, Шоу, Лавренева и других авторов. Во время Великой Отечественной войны театр работал в Усолье-Сибирском, а в здании Черемховского театра выступали Иркутский областной театр, Иркутский ТЮЗ, Украинский театр музыкальной комедии и драмы, а также Московский театр им. Ермоловой. После пожара в 1980 году театр переехал в здание ДК разреза «Черемховский», где находится по настоящее время.  В конце 1960-х — 1970-х годов в репертуаре театра появились пьесы драматургов, родившихся или живших в Черемхово. Так, одним из первых черемховский театр поставил «Прощание в июне» Александра Вампилова. Позже были поставлены спектакли по пьесам Михаила Варфоломеева «Полынь», «Святой и грешный». Режиссёр С. Казимировский ещё до выхода фильма В. Меньшова поставил спектакль «Любовь и голуби». В 2014 году театр провёл первый межрегиональный театральный фестиваль памяти В. П. Гуркина «Театральная провинция». В 2016 году состоялся второй фестиваль, в рамках которого была проведена режиссёрская лаборатория «ДомА» по пьесам В. П. Гуркина',NULL,NULL,NULL,NULL,'В учреждении есть фойе, зрительный зал, гардероб и другие помещения, необходимые для посещения спектаклей.',NULL,'Основной рекреационный потенциал театра — посещение спектаклей и участие в культурных мероприятиях. Также в театре проводятся экскурсии, во время которых можно увидеть закулисье, гримерные комнаты и комнату-музей, посвящённую Владимиру Гуркину.',NULL,'Время визита зависит от типа мероприятия. Спектакли обычно длятся от 1 до 2 часов с антрактом. Экскурсии могут занимать около 1 часа.',NULL,'запрет на проход в верхней одежде, в состоянии алкогольного или наркотического опьянения; запрет на пронос оружия, колюще-режущих предметов, пиротехники, легковоспламеняющихся жидкостей, больших хозяйственных и дорожных сумок; запрет на нахождение в театре без билета, в служебных помещениях за пределами зрительской зоны; запрет на разговоры, шум, приём пищи и напитков, разговоры по телефону во время спектакля.',NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:37','2026-06-01 04:48:37',1,1,0),(97,'Историко-краеведческий музей Черемховского района ',9,5,'Историко-краеведческий музей Черемховского района расположен в рабочем посёлке Михайловка Черемховского района Иркутской области. Это муниципальное казённое учреждение культуры, которое занимается сохранением и популяризацией истории региона.',1,52.9558300,103.2911310,'асфальтовое покрытие',38.0000000,1,'Музей открыт 6 мая 2005 года. У его создания стояли неравнодушные люди, которые хотели сохранить память о героическом труде жителей района, познакомить приезжих с культурой местности и задокументировать историю Черемховского района. В мае 2005 года открылся первый зал с экспозицией «Страницы истории Черемховского района XIX–XX вв.». На тот момент в музее насчитывалось около 400 экспонатов, фотографий и документов. В апреле 2006 года районный историко-краеведческий музей выделили в качестве самостоятельного учреждения, приняли Устав и зарегистрировали как муниципальное учреждение. К этому времени открылся второй зал — стационарная выставка «История района в Советское время»',NULL,NULL,NULL,NULL,'Музей расположен в отдельном нежилом одноэтажном здании площадью 213 м?. В нём есть: четыре зала (два постоянных и два выставочных); фондохранилище; центральное отопление; видеонаблюдение и система пожарной сигнализации (АПС); сторожевая охрана. Здание доступно для людей с ограниченными возможностями здоровья (ОВЗ).',NULL,'Музей ориентирован на культурно-познавательный туризм. Возможности: осмотр постоянных и временных экспозиций; участие в тематических выставках, лекциях и мастер-классах (например, по традиционным ремёслам); посещение мероприятий, таких как театрализованные представления или творческие вечера.',NULL,'1-1,5 ч.',NULL,'В музее действуют стандартные правила посещения: запрещено трогать экспонаты, фотографировать без разрешения, шуметь и мешать другим посетителям.','В музее проводятся экскурсии лекторами-экскурсоводами.',150.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:37','2026-06-01 04:48:37',1,1,0),(98,'Памятник Чехословацким легионерам',9,4,'Мемориальный знак посвящён памяти чехословацких воинов, которые «отдали жизнь на пути к свободной родине в 1918–1920 годах»',1,52.9553370,103.2883290,'асфальтовое покрытие',38.0000000,1,'Памятный знак был установлен летом 2011 года. Инициатива его создания принадлежала чешской делегации, которая посетила Черемховский район в 2011 году. Вопросы предоставления земельного участка, проведения работ по установке знака и его последующего содержания обсуждались в переписке между Ассоциацией «Военные мемориалы» и администрацией Черемховского района. Ассоциация действовала согласно российско-чешскому межправительственному соглашению о взаимном содержании военных захоронений, подписанному в 1999 году. Она обеспечивала финансирование проекта.  На стеле высечены имена 30 чехословацких легионеров, которые, согласно надписи, «отдали жизнь на пути к свободной родине» в период с мая 1918 по февраль 1920 года',NULL,NULL,NULL,NULL,'Информация о наличии смотровых площадок, информационных стендов, беседок, мусорных баков или туалетов в непосредственной близости от памятника в открытых источниках не упоминается.',NULL,'Это мемориальный объект, который может интересовать историков и туристов, изучающих события Гражданской войны.',NULL,'5-15 мин.',NULL,'Общепринятые правила поведения на мемориальных объектах: запрет на повреждение памятника, нарушение общественного порядка.',NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:37','2026-06-01 04:48:37',1,1,0),(99,'Обелиск воинам, павшим в годы Гражданской войны ',9,4,'Мемориал создан в память об односельчанах, чья жизнь оборвалась в трагическом 1918 году, а также о жителях, не вернувшихся с фронта Великой Отечественной войны.',1,52.9559270,103.2892880,'асфальтовое покрытие',38.0000000,1,'Обелиск воинам, павшим в годы Гражданской войны, в рабочем посёлке Михайловка Черемховского района Иркутской области создан в память об односельчанах, чья жизнь оборвалась в трагическом 1918 году, а также о жителях, не вернувшихся с фронта Великой Отечественной войны. Известно, что в 2006 году памятные доски на монументе обновили: на них появилось 114 фамилий. Это стало итогом работы краеведческого кружка учащихся школы №1 п. Михайловка под руководством Г. Г. Веретениной. В 2022 году по программе «Народные инициативы» проведена реконструкция памятника. Эскиз выполнил известный скульптор Иван Николаевич Зуев совместно с администрацией поселения.',NULL,NULL,NULL,NULL,'Известно, что в 2022 году в рамках реконструкции были проведены работы по обновлению памятника.',NULL,'Основная функция – мемориальная',NULL,'5-15 мин.',NULL,NULL,NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:37','2026-06-01 04:48:37',1,1,0),(100,'Церковь Василия Великого',9,NULL,'Церковь Василия Великого расположена в рабочем посёлке Михайловка Черемховского района Иркутской области по адресу: Вокзальная улица, 6Б. Она относится к Черемховскому благочинию Иркутской епархии Русской Православной Церкви.',1,52.9556600,103.2884380,'асфальтовое покрытие',38.0000000,1,'Строительство церкви началось в 1903 году на средства железнодорожного ведомства и за счёт пожертвований прихожан. Вчерне здание было завершено в 1906 году. 19 сентября 1909 года указом Синода был открыт самостоятельный приход при ещё строящейся церкви. Окончательно церковь обустроили в 1910 году, а 22 июля 1911 года киренский епископ Иоанн освятил её престол во имя святого Василия Великого. Церковь была построена из дерева на каменном фундаменте. Она имела архитектурный стиль эклектики и представляла собой крупный храм с широким восьмериком в центре равноконечного креста. Церковь венчал пологий восьмигранный шатёр со щипцами в основании граней. Входы в храм были устроены с трёх сторон, с крылечек-террас. В середине 1930-х годов церковь закрыли, колокольню разрушили, а здание сначала использовали как зернохранилище, затем в нём размещалась ремонтная мастерская, а позже — сельский клуб. Восстановление храма началось в 1990-х годах. Первая служба состоялась в августе 1997 года в полуразобранном здании. В ходе реставрации была проведена перепланировка, построена башня, подведены тепло, свет и вода. В настоящее время в храме по субботам, воскресеньям и праздникам совершается Божественная литургия, вечером проходит вечернее богослужение с исповедью.','В местных преданиях упоминается, что во время использования здания церкви под клуб происходили странные события: внезапно гас свет, раздавались непонятные звуки. Также рассказывалось о трагических случаях: внезапной смерти сторожа клуба и замерзании рабочего, который переконструировал здание.',NULL,NULL,NULL,NULL,NULL,'Это мемориальный и духовный объект, который может интересовать туристов, изучающих историю региона и архитектуру.',NULL,'30 мин.',NULL,'Запрещено фотографировать внутри храма без разрешения, курить, мусорить, вести себя неподобающим образом, следует одеваться скромно.',NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:37','2026-06-01 04:48:37',1,1,0),(101,'Железнодорожный вокзал Половина',9,NULL,'Железнодорожный вокзал Половина расположен в рабочем посёлке Михайловка Черемховского района. Станция относится к Восточно-Сибирской железной дороге и находится на участке Ангарск — Черемхово. Он сохранил архитектурные особенности конца XIX века',1,52.9563940,103.2830350,'асфальтовое покрытие, ж/д.',38.0000000,1,'Строительство станции 3-го класса Половина началось в 1896 году. Тогда же было заложено здание паровозного депо и вокзала. Станция получила название Половина, так как находилась примерно на половине расстояния между почтовыми станциями Черемхово и Тайтурка (позже Мальта). Вокзал — типичное деревянное здание на каменном фундаменте с железной крышей, построенное в стиле Министерства путей сообщения. В центральной части, на коньке, в ажурном деревянном обрамлении установлен флагшток.С правой стороны к зданию было пристроено помещение буфета и кухни. Вокзал отапливался шестью печами, облицованными кафельной плиткой, освещение было керосиновым. Вокзал сдан в постоянную эксплуатацию 1 января 1899 года. В 1902 году на перроне появился навес для торговли и перронная лавка. Для удобства посадки в поезд вдоль первого и второго путей были устроены деревянные пассажирская и промежуточная платформы.13 января 1920 года черемховские партизаны взяли под наблюдение, а на станции Половина — под охрану Колчака, его свиту и золотой запас России. Это произошло в контексте событий Гражданской войны, когда силы Колчака отступали под натиском Красной армии, а вокруг Транссибирской магистрали активно действовали повстанческие отряды. После задержания на станции Половина Колчака доставили в Иркутск, где он был передан эсеро-меньшевистскому Политцентру — временному правительству, контролировавшему город в тот период.','Встречается городская легенда о том, что поздней осенью 1994 года на станции Половина после 23:00 некий молодой человек якобы видел, как рядом с ним медленно проехал старинный поезд с надписью крупными латинскими буквами жёлтого цвета. Свидетель запомнил кондуктора в коричневой униформе и шапке с околышем, на нём был воротничок, пристёгнутый к сорочке. Также он заметил несколько человек в окнах вагонов. Прибытие поезда не объявлялось, он шёл по чужому пути.',NULL,NULL,NULL,'По данным на 2024 год, в здании вокзала есть зал ожидания и туалетные комнаты, которые работают круглосуточно. Также в зале ожидания расположена зона для зарядки мобильных устройств.',NULL,'Вокзал может быть интересен туристам, увлекающимся историей железнодорожного транспорта и Транссибирской магистрали. Рядом с ним сохранились другие исторические объекты: водонапорные башни, церковь Василия Великого.',NULL,'30 мин.',NULL,'В здании вокзала необходимо соблюдать правила, установленные ОАО «РЖД», включая запрет на курение, нарушение общественного порядка и т. д.',NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-01 04:48:38','2026-06-01 04:48:38',1,1,0);
