INSERT INTO `object_values` VALUES (1,'Местная',0),(2,'Региональная',0),(3,'Федеральная',0),(4,'местная: важный объект для жителей Онота и соседних сёл, место отдыха и туризма; региональная: пример успешного развития экотуризма в Иркутской области, поддержанный грантом;',1),(5,'Месторождение остаётся единственным в Восточной Сибири. Онотский тальк отличается высокой чистотой и отсутствием мышьяка, что делает его более эффективным по сравнению с тальком из месторождений Китая и Западной Сибири.',1),(6,'Площадь Ленина в Черемхово имеет местную значимость, так как связана с историей города и именем В. И. Ленина, с которым связаны некоторые страницы жизни черемховских шахтёров в 1920-е годы ',1),(7,'Музей является центром патриотического воспитания и краеведческой работы в Черемхово, играет роль в сохранении культурного наследия Иркутской области.',1),(8,'Граффити с изображением Александра Полещука в Черемхово (ул. Ференца Патаки, 4) имеет местную и региональную значимость, но не обладает федеральным статусом или статусом объекта культурного наследия (ООПТ).',1),(9,'Представляет собой современное культурное и образовательное учреждение, созданное в рамках национального проекта «Культура»',1),(10,'Сквер важен как место, где можно узнать об истории города и всего Приангарья',1);
/*!40000 ALTER TABLE `object_values` ENABLE KEYS */;
UNLOCK TABLES;

