INSERT INTO `seasons` VALUES (1,'Зима',0),(2,'Лето',0),(3,'Весна',0),(4,'Осень',0),(5,'Лучшее время для визита — лето и ранняя осень, когда погода позволяет комфортно гулять и фотографировать. Зимой доступ может быть затруднён из-за снега и льда, хотя река Иреть не замерзает.',1),(6,'лучшее время — лето и ранняя осень (июнь — сентябрь), когда погода комфортна и тропа проходима. Зимой маршрут доступен для подготовленных групп (лыжи, снегоступы). ',1),(7,'Посещать кладбище можно в любое время года, однако стоит учитывать погодные условия.',1),(8,'ha',1);
/*!40000 ALTER TABLE `seasons` ENABLE KEYS */;
